insert into public.courses(slug,title,description) values ('codezero','CodeZero','De cero a construir soluciones técnicas para SaaS.') on conflict(slug) do nothing;

insert into public.levels(course_id,level_number,slug,title,description,estimated_hours,sort_order)
select c.id,v.level_number,v.slug,v.title,v.description,v.hours,v.level_number
from public.courses c
cross join (values (1,'pensamiento-computacional','Pensamiento computacional','Aprende a resolver problemas de forma lógica antes de escribir código.',12),(2,'python-desde-cero','Python desde cero','Fundamentos de programación con Python: variables, tipos, condiciones, ciclos y funciones.',22),(3,'python-intermedio','Python intermedio y código limpio','Estructura programas más sólidos, mantenibles y profesionales.',22),(4,'algoritmos-estructuras-datos','Algoritmos y estructuras de datos','Aprende a organizar datos y resolver problemas mediante algoritmos.',22),(5,'git-terminal','Git, terminal y flujo profesional','Domina las herramientas fundamentales utilizadas en equipos de desarrollo.',12),(6,'bases-datos-sql','Bases de datos y SQL','Diseña, consulta y administra datos utilizando bases de datos relacionales.',18),(7,'desarrollo-web','Web: HTML + CSS + JavaScript','Construye aplicaciones web desde sus fundamentos.',25),(8,'backend-apis','Backend y APIs','Construye servicios backend y APIs para aplicaciones modernas.',22),(9,'ingenieria-software','Ingeniería de software','Aprende arquitectura, pruebas, calidad y prácticas profesionales de desarrollo.',20),(10,'capstone-profesional','Capstone · Proyecto profesional','Integra lo aprendido construyendo un proyecto técnico completo.',25),(11,'integraciones-apis-webhooks','Integraciones I · APIs y webhooks','Conecta sistemas mediante APIs, eventos y webhooks.',18),(12,'integraciones-saas-oauth','Integraciones II · SaaS, OAuth y automatización','Construye integraciones entre productos SaaS utilizando autenticación y automatización.',22),(13,'integraciones-empresariales','Integraciones III · Sistemas empresariales','Trabaja con integraciones y flujos habituales en entornos empresariales.',24),(14,'arquitectura-seguridad','Integraciones IV · Arquitectura y seguridad','Diseña integraciones seguras, escalables y mantenibles.',24),(15,'capstone-integraciones','Integraciones V · Capstone profesional','Construye una solución completa de integración SaaS con estándares profesionales.',28)) as v(level_number,slug,title,description,hours)
where c.slug='codezero'
on conflict(slug) do update set title=excluded.title,description=excluded.description,estimated_hours=excluded.estimated_hours,sort_order=excluded.sort_order;

insert into public.lessons(level_id,slug,title,description,content,estimated_minutes,sort_order,status)
select l.id,v.slug,v.title,v.description,v.content,v.minutes,v.sort_order,'published'
from public.levels l
