insert into public.level_projects(level_id,slug,title,brief,requirements,status)
select l.id,'capstone-producto-saas','Capstone · Producto SaaS','Diseña y documenta un producto SaaS funcional que integre frontend, backend, base de datos, autenticación y pruebas.','["Definir problema y usuario","Diseñar arquitectura","Implementar flujo principal","Documentar API y datos","Agregar pruebas","Preparar demo"]'::jsonb,'published'
from public.levels l where l.level_number=10
on conflict(slug) do update set title=excluded.title,brief=excluded.brief,requirements=excluded.requirements,status='published';

insert into public.level_projects(level_id,slug,title,brief,requirements,status)
select l.id,'capstone-integracion-enterprise','Capstone · Integración enterprise','Diseña una solución de integración SaaS empresarial segura, observable y resiliente de extremo a extremo.','["Definir sistemas origen y destino","Diseñar autenticación y seguridad","Implementar sincronización","Manejar reintentos e idempotencia","Agregar observabilidad","Entregar runbook y demo"]'::jsonb,'published'
